CREATE TABLE "tblDisputeHistory"
(
    "Id"             BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "DisputeId"      BIGINT                                  NOT NULL,
    "EventType"      VARCHAR(100)                            NOT NULL,
    "PreviousStatus" VARCHAR(100)                            NULL,
    "CurrentStatus"  VARCHAR(100)                            NOT NULL,
    "OccurredAt"     TIMESTAMP WITH TIME ZONE                NOT NULL,
    "Actor"          VARCHAR(100)                            NOT NULL,

    CONSTRAINT "PK_DisputeHistory" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DisputeHistory_Dispute" FOREIGN KEY ("DisputeId") REFERENCES "tblDispute" ("Id")
);

CREATE INDEX "IX_DisputeHistory_DisputeIdOccurredAtId" ON "tblDisputeHistory" ("DisputeId", "OccurredAt", "Id");
